{"experiments":[  
  {  
    "hypothesis":"Patient age at diagnosis is positively correlated with somatic tumor mutation burden, independent of pathologic stage.",  
    "experiment_plan":{  
      "objective":"Quantify the relationship between age at diagnosis and total number of somatic mutations per patient, adjusting for tumor stage.",  
      "steps":  
        "1. Load cleaned_clinical_data.csv and cleaned_mutations.csv.\n"  
       ,"deliverables":"Correlation coefficient and p‐value for age vs mutation count; linear regression summary (coefficients, p‐values, R²) adjusting for pathologic_stage; scatter plot with regression line."  
    }  
  },  
  {  
    "hypothesis":"Infiltrating lobular carcinoma and infiltrating ductal carcinoma exhibit distinct expression profiles of immune marker genes.",  
    "experiment_plan":{  
      "objective":"Identify immune‐related genes differentially expressed between lobular and ductal breast tumors.",  
      "steps":"1. Load cleaned_gene_expression.csv and cleaned_clinical_data.csv.\n"  
            ,"deliverables":"List of immune marker genes with log2‐fold changes and adjusted p‐values; heatmap of top differentially expressed immune genes; volcano plot highlighting significant genes."  
    }  
  },  
  {  
    "hypothesis":"Triple‐negative breast cancers (ER–/PR–/HER2–) have higher expression of immune checkpoint genes (e.g., CD274, PDCD1, CTLA4) compared to other subtypes.",  
    "experiment_plan":{  
      "objective":"Compare expression of key immune checkpoint genes between triple‐negative and non‐triple‐negative tumors.",  
      "steps":"1. Load cleaned_clinical_data.csv and cleaned_gene_expression.csv.\n"  
             ,"deliverables":"Boxplots of CD274, PDCD1, CTLA4 expression by subtype; Wilcoxon test p‐values for each gene; summary table of median expression values."  
    }  
  },  
  {  
    "hypothesis":"PIK3CA‐mutant breast tumors have fewer positive lymph nodes at surgery than PIK3CA wild-type tumors, when controlling for tumor size (pathologic_t).",  
    "experiment_plan":{  
      "objective":"Assess the impact of PIK3CA mutation status on lymph node positivity within T‐stage strata.",  
      "steps":"1. Load cleaned_mutations.csv and cleaned_clinical_data.csv.\n"  
             ,"deliverables":"Descriptive table of lymph_nodes_positive by PIK3CA status and T stage; Poisson regression or negative binomial model summary (incidence rate ratios and p‐values); bar plots of mean node counts."  
    }  
  },  
  {  
    "hypothesis":"Among patients who received neoadjuvant treatment, higher gene expression heterogeneity (per‐sample variance) is associated with shorter time to new tumor event.",  
    "experiment_plan":{  
      "objective":"Test whether global expression variability predicts early recurrence after neoadjuvant therapy.",  
      "steps":"1. Load cleaned_gene_expression.csv and cleaned_clinical_data.csv.\n"  
             ,"deliverables":"Correlation coefficient and p‐value between per‐sample expression SD and days_to_new_tumor; survival or linear regression summary adjusting for age; scatter plot of SD vs time to new tumor."  
    }  
  },  
  {  
    "hypothesis":"Black or African American patients have shorter overall survival than White patients, controlling for age at diagnosis and pathologic_stage.",  
    "experiment_plan":{  
      "objective":"Evaluate racial differences in breast cancer survival with multivariable Cox regression.",  
      "steps":"1. Load cleaned_clinical_data.csv.\n"  
             ,"deliverables":"Kaplan–Meier curves by race; Cox model summary (hazard ratios, 95% CI, p‐values) for race, age, and stage; log‐rank test p‐value."  
    }  
  },  
  {  
    "hypothesis":"High tumor mutation burden is associated with persistent tumor status at last follow-up (WITH TUMOR vs TUMOR FREE).",  
    "experiment_plan":{  
      "objective":"Determine whether patients with more somatic mutations are more likely to have residual disease after treatment.",  
      "steps":"1. Load cleaned_mutations.csv and cleaned_clinical_data.csv.\n"  
             ,"deliverables":"Logistic regression results for tumor_status ~ mutation_count (odds ratios, p‐values); boxplot of mutation counts by tumor_status; contingency table of high/low burden vs status."  
    }  
  },  
  {  
    "hypothesis":"Unsupervised transcriptomic clustering of tumors yields groups whose membership is significantly associated with HER2 IHC score categories.",  
    "experiment_plan":{  
      "objective":"Cluster patients by global gene expression and test association with HER2 IHC score.",  
      "steps":"1. Load cleaned_gene_expression.csv and cleaned_clinical_data.csv.\n"  
             ,"deliverables":"Cluster assignments for each patient; chi‐square test p‐value for cluster vs IHC score; PCA scatterplot colored by cluster and IHC category; heatmap of cluster centroids."  
    }  
  }  
]}
